169	    fn finish_success(&mut self, msg: &str) {
170	        let prefix = " ".repeat(self.indent);
171	        let theme = BivvyTheme::new();
172	        println!("{}{}", prefix, theme.format_success(msg));
173	    }
174	
175	    fn finish_error(&mut self, msg: &str) {
176	        let prefix = " ".repeat(self.indent);
