683	    // process group (e.g., `cargo run`), this triggers suspension.
684	    //
685	    // The SIGTTOU signal is ignored in main.rs, but these tests verify:
686	    //   1. The prompt code doesn't panic or crash on non-TTY
687	    //   2. Yes/no and multi-option selects produce consistent error behavior
688	    //
689	    // History: These tests were originally added in commit 09d5292, then
690	    // removed in commit 520c90c when the custom yes/no prompt was
691	    // reintroduced. Removing them allowed the SIGTTOU regression to go
692	    // undetected. They are restored here to prevent that from happening
693	    // again.
694	    //
695	    // If you need to change prompt_yes_no's output formatting, do so
696	    // WITHOUT removing these tests. The custom yes/no prompt (y/n
697	    // shortcuts, cursor guard, styled indicators) is a legitimate
698	    // customization — but it MUST coexist with SIGTTOU safety.
699	    // -----------------------------------------------------------------------
700	
701	    #[test]
702	    fn yes_no_prompt_does_not_crash_on_non_tty() {
703	        // Term::stdout() in test context is piped (non-TTY) because
704	        // cargo test captures stdout. prompt_yes_no detects non-TTY via
705	        // read_key() and returns an IO error — no SIGTTOU, no panic.
706	        let term = Term::stdout();
707	        if term.is_term() {
708	            return; // Skip under --nocapture with real TTY
709	        }
710	
711	        let options = vec![
712	            PromptOption {
713	                label: "Yes (y)".to_string(),
714	                value: "yes".to_string(),
715	            },
716	            PromptOption {
717	                label: "No (n)".to_string(),
718	                value: "no".to_string(),
719	            },
720	        ];
721	        let prompt = make_prompt(
722	            "rerun_step",
723	            PromptType::Select {
724	                options: options.clone(),
725	            },
726	            Some("yes"),
727	        );
728	
729	        // Call the REAL prompt code, not MockUI.
730	        // No SIGTTOU, no panic, no crash — just a clean IO error.
731	        let result = prompt_select(&prompt, &options, &term);
732	        assert!(result.is_err());
733	    }
734	
735	    #[test]
736	    fn yes_no_and_multi_option_selects_error_consistently() {
737	        // Verify that yes/no prompts and multi-option selects produce
738	        // the same kind of error on non-TTY. If yes/no had a different
739	        // code path that crashed instead of erroring, this test would
740	        // catch it.
741	        let term = Term::stdout();
742	        if term.is_term() {
743	            return; // Skip under --nocapture with real TTY
744	        }
745	
746	        // 2-option yes/no (takes the custom prompt_yes_no path)
747	        let yn_options = vec![
748	            PromptOption {
749	                label: "Yes (y)".to_string(),
750	                value: "yes".to_string(),
751	            },
752	            PromptOption {
753	                label: "No (n)".to_string(),
754	                value: "no".to_string(),
755	            },
756	        ];
757	        let yn_prompt = make_prompt(
758	            "yn",
759	            PromptType::Select {
760	                options: yn_options.clone(),
761	            },
762	            Some("yes"),
763	        );
764	
765	        // 3-option select (goes through dialoguer's Select)
766	        let multi_options = vec![
767	            PromptOption {
768	                label: "A".to_string(),
769	                value: "a".to_string(),
770	            },
771	            PromptOption {
772	                label: "B".to_string(),
773	                value: "b".to_string(),
774	            },
775	            PromptOption {
776	                label: "C".to_string(),
777	                value: "c".to_string(),
778	            },
779	        ];
780	        let multi_prompt = make_prompt(
781	            "multi",
782	            PromptType::Select {
783	                options: multi_options.clone(),
784	            },
785	            Some("a"),
786	        );
787	
788	        // Both must error on non-TTY — neither should panic or crash.
789	        let result_yn = prompt_select(&yn_prompt, &yn_options, &term);
790	        let result_multi = prompt_select(&multi_prompt, &multi_options, &term);
791	
792	        assert!(result_yn.is_err(), "yes/no should error on non-TTY");
793	        assert!(result_multi.is_err(), "multi should error on non-TTY");
794	    }
795	}
