9	};
10	
11	/// UI implementation for non-interactive mode.
12	///
13	/// Used by every command (init, status, list, run, …) when running
14	/// without a TTY. Run-path workflow chrome lives in
15	/// [`crate::runner::display::NonInteractiveWorkflowDisplay`] — this
16	/// type only handles generic [`UserInterface`] traits.
17	pub struct NonInteractiveUI {
18	    mode: OutputMode,
19	    #[allow(dead_code)]
20	    is_ci: bool,
21	}
22	
23	impl NonInteractiveUI {
24	    /// Create a new non-interactive UI.
25	    pub fn new(mode: OutputMode) -> Self {
26	        Self {
27	            mode,
28	            is_ci: crate::shell::is_ci(),
29	        }
30	    }
31	
32	    /// Create with explicit CI flag (for testing).
33	    pub fn with_ci(mode: OutputMode, is_ci: bool) -> Self {
34	        Self { mode, is_ci }
35	    }
36	}
37	
38	impl OutputWriter for NonInteractiveUI {
39	    fn message(&mut self, msg: &str) {
40	        if self.mode.shows_status() {
41	            println!("{}", msg);
42	        }
43	    }
44	
45	    fn success(&mut self, msg: &str) {
46	        if self.mode.shows_status() {
47	            println!("✓ {}", msg);
48	        }
49	    }
50	
51	    fn warning(&mut self, msg: &str) {
52	        if self.mode.shows_status() {
53	            eprintln!("⚠ {}", msg);
54	        }
55	    }
56	
57	    fn error(&mut self, msg: &str) {
58	        eprintln!("✗ {}", msg);
59	    }
60	
61	    fn show_hint(&mut self, hint: &str) {
62	        if self.mode.shows_status() {
63	            println!("  💡 {}", hint);
64	        }
65	    }
66	
67	    fn show_error_block(&mut self, command: &str, output: &str, hint: Option<&str>, indent: usize) {
68	        let pad = " ".repeat(indent);
69	        eprintln!();
70	        eprintln!("{}┌─ Command ──────────────────────────", pad);
71	        eprintln!("{}│ {}", pad, command);
72	        if !output.is_empty() {
73	            eprintln!("{}├─ Output ───────────────────────────", pad);
74	            for line in output.lines() {
75	                eprintln!("{}│ {}", pad, line);
76	            }
77	        }
78	        eprintln!("{}└────────────────────────────────────", pad);
79	        if let Some(h) = hint {
80	            eprintln!();
81	            eprintln!("{}Hint: {}", pad, h);
82	        }
83	    }
84	}
85	
86	impl Prompter for NonInteractiveUI {
87	    fn prompt(&mut self, prompt: &Prompt) -> Result<PromptResult> {
88	        let is_multiselect = matches!(prompt.prompt_type, PromptType::MultiSelect { .. });
89	
90	        // Check environment override (KEY=value, e.g. BUMP=minor).
91	        // This is handled by prompt_user for TerminalUI, but
92	        // NonInteractiveUI doesn't call prompt_user, so check here too.
93	        if let Some(result) = super::prompts::env_override(prompt) {
94	            return Ok(result);
95	        }
96	
97	        // Use default
98	        if let Some(default) = &prompt.default {
99	            if is_multiselect {
100	                let values: Vec<String> =
101	                    default.split(',').map(|s| s.trim().to_string()).collect();
102	                return Ok(PromptResult::Strings(values));
103	            }
104	            return Ok(PromptResult::String(default.clone()));
105	        }
106	
107	        Err(BivvyError::ConfigValidationError {
108	            message: format!(
109	                "Cannot prompt for '{}' in non-interactive mode (no default value)",
110	                prompt.key
111	            ),
112	        })
113	    }
114	}
