    // Read key — terminal is already in raw mode so read_key() is a
    // no-op mode switch (raw→raw). Characters are available immediately.
    // EOF (terminal closed / Ctrl+D) selects "no".
    let key = match term.read_key() {
        Ok(k) => k,
        Err(_) => {
            let no_idx = options
                .iter()
                .position(|o| o.value == "no")
                .unwrap_or(default_idx);
            sel = no_idx;
            Key::Enter
        }
    };

    let chosen = match key {
        Key::Char('y') | Key::Char('Y') => options.iter().position(|o| o.value == "yes"),
        Key::Char('n') | Key::Char('N') => options.iter().position(|o| o.value == "no"),
        Key::Enter | Key::Char(' ') => Some(sel),
        Key::Escape | Key::Char('\x04') => {
            // Treat Escape and Ctrl+D as "no" (abort / EOF).
            let no_idx = options
                .iter()
                .position(|o| o.value == "no")
                .unwrap_or(default_idx);
            Some(no_idx)
        }
        Key::ArrowDown | Key::Tab | Key::Char('j') => {
            sel = (sel + 1) % options.len();
            None
        }
        Key::ArrowUp | Key::BackTab | Key::Char('k') => {
            sel = (sel + options.len() - 1) % options.len();
            None
        }
        _ => None,
    };

